+static const struct pci_epf_device_id scsit_pci_epf_ids[] = {
+	{ .name = "scsit_pci_epf" },
+	{},
+};
+
+static struct pci_epf_ops scsit_pci_epf_ops = {
+	.bind	 = scsit_pci_epf_bind,
+	.unbind	 = scsit_pci_epf_unbind,
+	.add_cfs = scsit_pci_epf_add_cfs,
+};
