+static struct pci_epf_driver scsit_pci_epf_driver = {
+	.driver.name	= "scsit_pci_epf",
+	.probe		= scsit_pci_epf_probe,
+	.id_table	= scsit_pci_epf_ids,
+	.ops		= &scsit_pci_epf_ops,
