+	if (r->alloc_capable) {
+		for_each_resource_ctrl(ctrl, r) {
+			list_for_each_entry(em_ctrl, &ctrl->emulated_by, entry) {
+				dom = mpam_get_ctrl_domain_from_nid(nid, res, em_ctrl);
+				if (WARN_ON_ONCE(!dom))
